docstring:
For every word `x` and every `i` below `x.count_ones()`, `x.select_ones(i)`
returns `Some(r)` with `x.rank_ones(r) == Some(i)` and `x.get(r) == Some(true)`;
`x.select_ones(x.count_ones())` returns `None`.

pbt.assertion:
for lhs_value in &[I8(lhs), I16(lhs as i16), I32(lhs as i32), I64(lhs as i64)],
    rhs_value in &[I8(rhs), I16(rhs as i16), I32(rhs as i32), I64(rhs as i64)]:
  let int_ordering = lhs.cmp(&rhs);
  prop_assert_eq!(lhs_value.cmp(rhs_value), int_ordering);
  prop_assert_eq!(rhs_value.cmp(lhs_value), int_ordering.reverse());

for lhs_value in &[U8(lhs), U16(lhs as u16), U32(lhs as u32), U64(lhs as u64)],
    rhs_value in &[U8(rhs), U16(rhs as u16), U32(rhs as u32), U64(rhs as u64)]:
  let int_ordering = lhs.cmp(&rhs);
  prop_assert_eq!(lhs_value.cmp(rhs_value), int_ordering);
  prop_assert_eq!(rhs_value.cmp(lhs_value), int_ordering.reverse());

for lhs_value in &[U8(lhs), U16(lhs as u16), U32(lhs as u32), U64(lhs as u64)],
    rhs_value in &[U8(rhs), U16(rhs as u16), U32(rhs as u32), U64(rhs as u64)]:
  let int_is_equal = lhs.eq(&rhs);
  prop_assert_eq!(lhs_value.eq(rhs_value), int_is_equal);
  prop_assert_eq!(rhs_value.eq(lhs_value), int_is_equal);

let (got, _) = get_suffix_forward(&bytes, SuffixKind::Maximal);  // (&needle[s.pos..], s.period) with s = Suffix::forward(needle, kind)
let expected = naive_maximal_suffix_forward(&bytes);            // last element of the sorted list of suffixes bytes[i..], i < len
got == expected

let (got, _) = get_suffix_reverse(&bytes, SuffixKind::Maximal);  // (&needle[..s.pos], s.period) with s = Suffix::reverse(needle, kind)
let expected = naive_maximal_suffix_reverse(&bytes);            // reverse(naive_maximal_suffix_forward(reverse(bytes)))
expected == got

let (a, b) = (max(a,b), min(a,b)); let m = Matrix::from_u64(a, b);
let (c, d) = m.apply_u128(a as u128, b as u128);
assert!(c >= d); assert_eq!(c, gcd(a as u128, b as u128)); assert_eq!(d, 0)

let (a, b) = (max(a,b), min(a,b)); let s = a.leading_zeros(); let (sa, sb) = (a << s, b << s);
let m = Matrix::from_u64_prefix((sa >> 64) as u64, (sb >> 64) as u64); let (c, d) = m.apply_u128(a, b);
assert!(c >= d); if m == Matrix::IDENTITY { assert_eq!(c, a); assert_eq!(d, b); }
else { assert!(c <= a); assert!(d < b); assert_eq!(gcd(a, b), gcd(c, d)); }

if let Some(expected) = factorial_reference(n) {
    prop_assert_eq!(factorial(n_u64), Ok(expected));
} else {
    prop_assert_eq!(factorial(n_u64), Err(CombinatoricsError::FactorialOverflow(n_u64)));
}

if n <= 34 {
    prop_assert!(factorial(n_u64).is_ok());
} else {
    prop_assert_eq!(factorial(n_u64), Err(CombinatoricsError::FactorialOverflow(n_u64)));
}

if k > n {
    prop_assert_eq!(permutations(n_u64, k_u64), Err(CombinatoricsError::KExceedsN { n: n_u64, k: k_u64 }));
} else if let Some(expected) = permutations_reference(n, k) {
    prop_assert_eq!(permutations(n_u64, k_u64), Ok(expected));
} else {
    prop_assert_eq!(permutations(n_u64, k_u64), Err(CombinatoricsError::PermutationOverflow { n: n_u64, k: k_u64 }));
}
